DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_1','The Wandering Circus[NEWLINE]Worker logistics and recurring local cultural festivals[NEWLINE]Culture; Science or Diplomacy from developed cities[NEWLINE][NEWLINE]Use Carnival Crews for real improvements, then bring them through eligible city centres to stage festivals. A good route turns one worker''s travel into several timed local benefits without leaving the countryside unfinished.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_2','Develop food and production with the faster-moving Crew. Plan its route past the capital and future cities. A festival is useful, but the ordinary improvements it displaces may be more important in a weak opening.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_3','Build Ticket Offices in worthwhile cities and stagger Crew visits around each city''s independent cooldown. After a festival starts, the Crew can leave and work elsewhere; extra Crews do not stack another show in the same city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_4','Maintain a developed network of regular festivals while building the actual Tourism, research or diplomatic infrastructure for victory. Flat festival Culture is support for policy development, not an automatic source of Tourism.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_5','- Reusable Crews can combine ordinary Worker jobs with festival preparation.[NEWLINE]- Several cities can host independent festivals at once.[NEWLINE]- Ticket Offices add permanent Culture and an additional festival-time incentive.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_6','- Festivals have a short fixed duration and a longer local cooldown.[NEWLINE]- Crew travel or parking has an opportunity cost in unfinished improvements.[NEWLINE]- Extra Crews cannot stack the same city''s festival yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_7','- Threaten travelling Crews and force escort or repair duties.[NEWLINE]- Pressure cities during their inactive local cooldown.[NEWLINE]- Use mobile attacks to disrupt the logistical route linking the next festivals.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_8','- Leaving every Crew parked in a city despite unbuilt critical improvements.[NEWLINE]- Expecting captured foreign Workers to trigger a show.[NEWLINE]- Treating ordinary Culture generation as equivalent to Tourism pressure.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The First Night: On a developed wide map, repeat local festivals can supply ongoing output after the most accessible one-time Memories have been earned.[NEWLINE][NEWLINE]Saba: Festival access is not tied to a River or Desert city centre, providing flexibility on mixed terrain.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Fast land raiders can threaten the Crews and travel corridors that sustain the schedule.[NEWLINE][NEWLINE]The Filthy Realm: City disruption and forced emergency logistics can interrupt a carefully staggered festival economy.');
