INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_BACKGROUND','Use Carnival Crews for real improvements, then bring them through eligible city centres to stage festivals. A good route turns one worker''s travel into several timed local benefits without leaving the countryside unfinished.');
