INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_STRATEGY','Use Carnival Crews for real improvements, then bring them through eligible city centres to stage festivals. A good route turns one worker''s travel into several timed local benefits without leaving the countryside unfinished.[NEWLINE][NEWLINE]Develop food and production with the faster-moving Crew. Plan its route past the capital and future cities. A festival is useful, but the ordinary improvements it displaces may be more important in a weak opening.[NEWLINE][NEWLINE]Build Ticket Offices in worthwhile cities and stagger Crew visits around each city''s independent cooldown. After a festival starts, the Crew can leave and work elsewhere; extra Crews do not stack another show in the same city.[NEWLINE][NEWLINE]Maintain a developed network of regular festivals while building the actual Tourism, research or diplomatic infrastructure for victory. Flat festival Culture is support for policy development, not an automatic source of Tourism.');
