INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_LEADER_TEXT_2','Develop food and production with the faster-moving Crew. Plan its route past the capital and future cities. A festival is useful, but the ordinary improvements it displaces may be more important in a weak opening.[NEWLINE][NEWLINE]Build Ticket Offices in worthwhile cities and stagger Crew visits around each city''s independent cooldown. After a festival starts, the Crew can leave and work elsewhere; extra Crews do not stack another show in the same city.[NEWLINE][NEWLINE]Maintain a developed network of regular festivals while building the actual Tourism, research or diplomatic infrastructure for victory. Flat festival Culture is support for policy development, not an automatic source of Tourism.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEWANDERINGCIRCUS_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The First Night: On a developed wide map, repeat local festivals can supply ongoing output after the most accessible one-time Memories have been earned.[NEWLINE][NEWLINE]Saba: Festival access is not tied to a River or Desert city centre, providing flexibility on mixed terrain.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Fast land raiders can threaten the Crews and travel corridors that sustain the schedule.[NEWLINE][NEWLINE]The Filthy Realm: City disruption and forced emergency logistics can interrupt a carefully staggered festival economy.');
